<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { AlertTriangle, ExternalLink, Focus, Network, RotateCcw, Sparkles, X, ZoomIn, ZoomOut } from '@lucide/vue'
import type { ActivityEvent, Group, GroupMember, MutualFriend, UserProfile } from './api'
import { buildStrangerGraph, relationshipInsights, type RelationshipInsight, type StrangerGraphNode } from './stranger-network'

const props = defineProps<{
  self:{ id:string; displayName:string; imageUrl?:string }
  target:UserProfile
  mutuals:MutualFriend[]
  groups:Group[]
  members:GroupMember[]
  events:ActivityEvent[]
  mediaUrl:(value?:string)=>string
}>()
const emit = defineEmits<{ openUser:[userId:string] }>()
const hoveredID = ref('')
const selectedID = ref('')
const zoom = ref(1)
const showCandidates = ref(true)
const selectedInsight = ref<RelationshipInsight|null>(null)
const graph = computed(() => buildStrangerGraph(props))
const insights = computed(() => relationshipInsights(props))
const visibleNodes = computed(() => showCandidates.value ? graph.value.nodes : graph.value.nodes.filter(item=>item.kind!=='candidate'&&item.kind!=='group'))
const visibleIDs = computed(() => new Set(visibleNodes.value.map(item=>item.id)))
const visibleEdges = computed(() => graph.value.edges.filter(item=>visibleIDs.value.has(item.source)&&visibleIDs.value.has(item.target)))
const nodeByID = computed(() => new Map(graph.value.nodes.map(item=>[item.id,item])))
const focusedID = computed(() => selectedID.value || hoveredID.value)
const focusedNode = computed(() => graph.value.nodes.find(item=>item.id===focusedID.value))
const focusedRelations = computed(() => visibleEdges.value.filter(edge=>edge.source===focusedID.value||edge.target===focusedID.value).map(edge=>({
  ...edge,
  peer:nodeByID.value.get(edge.source===focusedID.value?edge.target:edge.source),
})))
const neighborIDs = computed(() => {
  const ids = new Set<string>(focusedID.value ? [focusedID.value] : [])
  for (const edge of visibleEdges.value) if (edge.source===focusedID.value) ids.add(edge.target); else if (edge.target===focusedID.value) ids.add(edge.source)
  return ids
})
function nodeRadius(node:StrangerGraphNode) { return node.kind==='target'?31:node.kind==='self'?27:node.kind==='group'?23:node.kind==='mutual'&&graph.value.mutualCount>=40?14:18 }
function renderNodeImage(node:StrangerGraphNode) { return Boolean(node.imageUrl) && (node.kind!=='mutual' || graph.value.mutualCount<=60 || focusedID.value===node.id) }
function nodeClass(node:StrangerGraphNode) { return { selected:selectedID.value===node.id, dimmed:focusedID.value&&!neighborIDs.value.has(node.id), [node.kind]:true } }
function edgeClass(edge:{source:string;target:string;kind:string}) { return { active:focusedID.value&&(edge.source===focusedID.value||edge.target===focusedID.value), dimmed:focusedID.value&&edge.source!==focusedID.value&&edge.target!==focusedID.value, [edge.kind]:true } }
function selectNode(node:StrangerGraphNode) { selectedID.value=node.id }
function openNode(node:StrangerGraphNode) { if (node.kind==='target'||node.kind==='mutual'||node.kind==='candidate') emit('openUser',node.id) }
function reset() { selectedID.value=''; hoveredID.value=''; zoom.value=1 }
function canOpen(node?:StrangerGraphNode) { return Boolean(node && ['target','mutual','candidate'].includes(node.kind)) }
function kindLabel(kind:StrangerGraphNode['kind']) { return ({self:'自己',target:'目标人物',mutual:'共同好友',group:'公开群组',candidate:'可见群组成员'} as const)[kind] }
function edgeLabel(kind:string) { return ({friend:'你的好友',mutual:'对方的好友',membership:'目标公开加入',candidate:'公开成员名单',co_presence:'本机同实例观察'} as Record<string,string>)[kind] || kind }
function edgePath(edge:{source:string;target:string;kind:string}) {
  const source=nodeByID.value.get(edge.source); const target=nodeByID.value.get(edge.target)
  if(!source||!target)return ''
  if(edge.kind==='friend'&&source.kind==='self'&&target.kind==='mutual') return `M ${source.x+nodeRadius(source)} ${source.y} H 225 V ${target.y} H ${target.x-nodeRadius(target)}`
  if(edge.kind==='mutual'&&source.kind==='mutual'&&target.kind==='target') return `M ${source.x+nodeRadius(source)} ${source.y} H 775 V ${target.y} H ${target.x-nodeRadius(target)}`
  const offset=edge.kind==='co_presence'?-34:34
  const middle=(source.x+target.x)/2+offset
  return `M ${source.x} ${source.y} Q ${middle} ${(source.y+target.y)/2} ${target.x} ${target.y}`
}
function onKeydown(event:KeyboardEvent) { if(event.key==='Escape') selectedID.value='' }
onMounted(()=>window.addEventListener('keydown',onKeydown))
onBeforeUnmount(()=>window.removeEventListener('keydown',onKeydown))
function toneLabel(value:string) { return value==='strong'?'关系信号':value==='caution'?'边界提醒':'参考判断' }
function verdictLabel(item:RelationshipInsight) { return item.tone==='caution'?'边界条件成立':item.confidence==='高'?'现有证据支持':item.confidence==='中'?'部分证据支持':'证据仍然不足' }
function verdictClass(item:RelationshipInsight) { return item.tone==='caution'?'caution':item.confidence==='高'?'supported':item.confidence==='中'?'partial':'insufficient' }
function evidenceSource(item:RelationshipInsight) {
  if (['mutual-route','friend-slice','mutual-activity','network-shape','contact-route'].includes(item.id)) return '共同好友与关系计数接口'
  if (item.id==='mutual-cross-source') return '共同好友接口 + 可见群组成员接口'
  if (item.id==='mutual-co-presence') return '共同好友接口 + 本机 VRChat 活动日志'
  if (['group-overlap','circle-bridge','circle-concentration'].includes(item.id)) return '用户公开群组与可见成员接口'
  if (['local-observation','co-presence'].includes(item.id)) return '本机 VRChat 活动日志'
  return '用户公开资料接口'
}
function limitations(item:RelationshipInsight) {
  if (item.id==='co-presence'||item.id==='local-observation'||item.id==='mutual-co-presence') return ['日志只能证明本机在某个时间点观察到事件','同时出现不等于双方交谈或发生互动','客户端未运行期间没有覆盖']
  if (item.id.includes('group')||item.id.includes('circle')) return ['群组成员关系不等于好友关系','隐藏群组和不可见成员不在样本中','大型群组的公开成员只读取有限页']
  if (['mutual-route','friend-slice','mutual-cross-source','mutual-activity'].includes(item.id)) return ['共同好友只展示双方好友列表的交集，不是对方完整好友列表','接口结果受双方隐私设置影响','无法据此判断关系亲疏或互动频率']
  return ['只使用当前账号可见字段','资料缺失可能来自隐私设置而非真实不存在','结论不能扩展到现实身份或个人品质']
}
function verificationSteps(item:RelationshipInsight) {
  if (item.id==='co-presence'||item.id==='local-observation'||item.id==='mutual-co-presence') return ['继续积累不同日期的本机日志','核对事件时间和实例 ID','等待重复证据后再提高可信度']
  if (item.id.includes('group')||item.id.includes('circle')) return ['重新扫描可见群组确认成员仍然存在','检查该人物是否跨多个独立群组重复出现','结合共同好友或同房日志交叉验证']
  if (['mutual-route','friend-slice','mutual-cross-source','mutual-activity'].includes(item.id)) return ['刷新共同好友接口','观察桥接节点是否在不同证据来源重复出现','通过正常社交渠道确认，而非依赖推测']
  return ['刷新目标公开资料','比较后续快照是否稳定','寻找第二种独立数据来源交叉验证']
}
</script>

<template>
  <article class="relationship-lab">
    <header><div><Network :size="17" /><span><strong>复杂关系网 · {{ graph.mutualCount }} 位共同好友全部列出</strong><small>从左到右阅读：自己 → 共同好友交集 → 目标；单击锁定，双击打开档案</small></span></div><div class="graph-actions"><label><input v-model="showCandidates" type="checkbox" />显示辅助群组证据</label><button @click="zoom=Math.max(.7,zoom-.1)"><ZoomOut :size="14" /></button><span>{{ Math.round(zoom*100) }}%</span><button @click="zoom=Math.min(1.5,zoom+.1)"><ZoomIn :size="14" /></button><button @click="reset"><RotateCcw :size="14" />重置</button></div></header>
    <div class="lab-grid">
      <div class="graph-canvas" @click.self="selectedID=''">
        <div v-if="selectedID && focusedNode" class="focus-chip"><Focus :size="13" /><span>已锁定 <b>{{ focusedNode.label }}</b></span><button @click="selectedID=''"><X :size="12" /></button></div>
        <svg class="relationship-graph-svg" :viewBox="`0 0 1000 ${graph.height}`" :style="{ height: `${graph.height}px` }" role="img" aria-label="自己通过全部共同好友与目标相交的分层关系图">
          <defs><clipPath v-for="node in visibleNodes" :id="`stranger-clip-${node.id}`" :key="`clip-${node.id}`"><circle :cx="node.x" :cy="node.y" :r="nodeRadius(node)-3" /></clipPath></defs>
          <g class="graph-guides"><text x="80" y="34" text-anchor="middle">关系起点</text><text x="500" y="34" text-anchor="middle">全部共同好友交集（{{ graph.mutualCount }}）</text><text x="920" y="34" text-anchor="middle">关系目标</text><line x1="180" y1="52" x2="180" :y2="graph.height-30"/><line x1="820" y1="52" x2="820" :y2="graph.height-30"/></g>
          <g :transform="`translate(${500-500*zoom} ${graph.height/2-graph.height/2*zoom}) scale(${zoom})`">
            <g class="edges"><path v-for="(edge,index) in visibleEdges" :key="`${edge.source}-${edge.target}-${index}`" :d="edgePath(edge)" :class="edgeClass(edge)" /></g>
            <g v-for="node in visibleNodes" :key="node.id" class="relation-node" :class="nodeClass(node)" role="button" tabindex="0" :aria-label="`${kindLabel(node.kind)} ${node.label}`" @mouseenter="hoveredID=node.id" @mouseleave="hoveredID=''" @click.stop="selectNode(node)" @dblclick.prevent.stop="openNode(node)" @keydown.enter.prevent="openNode(node)" @keydown.space.prevent="selectNode(node)">
              <circle class="node-halo" :cx="node.x" :cy="node.y" :r="nodeRadius(node)+4" /><circle class="node-body" :cx="node.x" :cy="node.y" :r="nodeRadius(node)" />
              <image v-if="renderNodeImage(node)" :href="mediaUrl(node.imageUrl)" :x="node.x-nodeRadius(node)+3" :y="node.y-nodeRadius(node)+3" :width="nodeRadius(node)*2-6" :height="nodeRadius(node)*2-6" preserveAspectRatio="xMidYMid slice" :clip-path="`url(#stranger-clip-${node.id})`" />
              <text v-else :x="node.x" :y="node.y+4" text-anchor="middle">{{ node.kind==='group'?'群':node.label.slice(0,1) }}</text><text class="node-label" :x="node.x" :y="node.y+nodeRadius(node)+15" text-anchor="middle">{{ node.label }}</text>
            </g>
          </g>
        </svg>
        <div class="graph-legend"><span><i class="self"></i>自己</span><span><i class="target"></i>目标</span><span><i class="mutual"></i>共同好友</span><span><i class="group"></i>辅助群组</span><span><i class="candidate"></i>群组候选</span><span><i class="edge self-edge"></i>你 ↔ 共同好友</span><span><i class="edge target-edge"></i>共同好友 ↔ 目标</span><span><i class="edge observed-edge"></i>同实例观察</span></div>
        <div v-if="graph.hiddenNodes" class="hidden-note">为保证流畅，图中省略 {{ graph.hiddenNodes }} 个低优先级节点</div>
      </div>
      <aside class="node-inspector"><template v-if="focusedNode"><span class="kind-label">{{ selectedID ? '已锁定' : '悬停预览' }} · {{ kindLabel(focusedNode.kind) }}</span><h3>{{ focusedNode.label }}</h3><p>{{ focusedNode.detail }}</p><dl><div><dt>直接关系</dt><dd>{{ focusedRelations.length }}</dd></div><div><dt>节点类型</dt><dd>{{ kindLabel(focusedNode.kind) }}</dd></div><div><dt>证据性质</dt><dd>{{ focusedRelations.some(edge=>edge.evidence==='observed')?'含本机观察':'接口确认' }}</dd></div></dl><div v-if="focusedRelations.length" class="relation-list"><strong>逐条关系</strong><span v-for="edge in focusedRelations" :key="`${edge.source}-${edge.target}-${edge.kind}`"><b>{{ edgeLabel(edge.kind) }}</b><em>{{ edge.peer?.label }}</em></span></div><button v-if="canOpen(focusedNode)" type="button" class="open-profile" @click="openNode(focusedNode)"><ExternalLink :size="14" />打开完整档案</button><p v-if="selectedID" class="open-hint">单击锁定不会因移开鼠标而消失；双击节点或点击上方按钮均可打开档案，Esc 解锁。</p></template><template v-else><Network :size="24" /><h3>悬停预览，单击锁定</h3><p>锁定后只突出它的一跳关系；人物节点支持双击或 Enter 打开档案。</p></template></aside>
    </div>
    <section class="inference-section"><header><div><Sparkles :size="16" /><strong>基于现有证据的关系推测</strong></div><span>点击卡片查看论证、反证边界与验证方法</span></header><div class="inference-grid"><button v-for="item in insights" :key="item.id" type="button" class="inference-card" :data-tone="item.tone" @click="selectedInsight=item"><div><span>{{ toneLabel(item.tone) }}</span><b>可信度 {{ item.confidence }}</b></div><h4>{{ item.title }}</h4><p>{{ item.summary }}</p><ul><li v-for="evidence in item.evidence.slice(0,3)" :key="evidence">{{ evidence }}</li></ul><em>点击查看完整论证 →</em></button></div><div class="inference-warning"><AlertTriangle :size="14" />图中“群组成员”只说明成员列表可见；除共同好友接口明确返回的节点外，不推断两个人互为好友。</div></section>
    <div v-if="selectedInsight" class="proof-overlay" @click.self="selectedInsight=null"><article class="proof-dialog"><header><div><span>关系推测论证卡</span><h3>{{ selectedInsight.title }}</h3></div><button @click="selectedInsight=null"><X :size="18" /></button></header><div class="verdict" :data-state="verdictClass(selectedInsight)"><span>{{ verdictLabel(selectedInsight) }}</span><b>可信度 {{ selectedInsight.confidence }}</b></div><section><h4>当前结论</h4><p>{{ selectedInsight.summary }}</p></section><section><h4>直接证据</h4><div class="proof-source">数据来源：{{ evidenceSource(selectedInsight) }}</div><ol><li v-for="evidence in selectedInsight.evidence" :key="evidence"><b>支持</b><span>{{ evidence }}</span></li></ol></section><section><h4>它不能证明什么</h4><ul class="limit-list"><li v-for="item in limitations(selectedInsight)" :key="item">{{ item }}</li></ul></section><section><h4>如何进一步验证</h4><ol class="verify-list"><li v-for="(item,index) in verificationSteps(selectedInsight)" :key="item"><b>{{ index+1 }}</b><span>{{ item }}</span></li></ol></section><footer><AlertTriangle :size="14" />“是否属实”按当前证据判断；数据刷新、隐私权限或样本范围变化后，结论可能改变。</footer></article></div>
  </article>
</template>

<style scoped>
.relationship-lab{margin-top:12px;border:1px solid var(--line);border-radius:9px;background:var(--surface);overflow:hidden}.relationship-lab>header,.inference-section>header{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:10px 12px;border-bottom:1px solid var(--line)}.relationship-lab>header>div:first-child,.inference-section>header>div{display:flex;align-items:center;gap:7px}.relationship-lab>header svg,.inference-section>header svg{color:var(--accent)}.relationship-lab>header span span,.relationship-lab>header strong,.relationship-lab>header small{display:block}.relationship-lab>header strong{font-size:11px}.relationship-lab>header small{margin-top:2px;color:var(--muted);font-size:8px}.graph-actions{display:flex;align-items:center;gap:4px}.graph-actions label,.graph-actions button,.graph-actions>span{height:28px;display:flex;align-items:center;gap:4px;padding:0 7px;border:1px solid var(--line);border-radius:5px;background:var(--surface-muted);color:var(--ink-soft);font-size:8px}.graph-actions button{cursor:pointer}.graph-actions>span{min-width:42px;justify-content:center}.lab-grid{display:grid;grid-template-columns:minmax(0,1fr) 220px}.graph-canvas{position:relative;min-height:540px;overflow:hidden;background:radial-gradient(circle at 47% 50%,color-mix(in srgb,var(--accent) 7%,transparent),transparent 40%),var(--surface-muted)}.graph-canvas>.relationship-graph-svg{display:block;width:100%;height:540px}.edges path{fill:none;stroke:var(--line-strong);stroke-width:1.25;opacity:.58;transition:opacity .15s,stroke-width .15s}.edges path.membership{stroke:color-mix(in srgb,#9a6bda 55%,var(--line))}.edges path.candidate{stroke:color-mix(in srgb,#c38b45 45%,var(--line))}.edges path.co_presence{stroke:var(--accent);stroke-dasharray:5 5}.edges path.active{stroke:var(--accent);stroke-width:2.4;opacity:1}.edges path.dimmed{opacity:.04}.relation-node{cursor:pointer;outline:none;transition:opacity .15s}.relation-node:focus .node-halo{stroke:var(--accent);stroke-width:4}.relation-node.dimmed{opacity:.12}.node-halo{fill:var(--surface);stroke:var(--line);stroke-width:2}.node-body{fill:#78848f}.relation-node.self .node-halo{stroke:#4f8bc9}.relation-node.target .node-halo{stroke:var(--accent);stroke-width:4}.relation-node.mutual .node-body{fill:#5f8b72}.relation-node.group .node-body{fill:#8569a9}.relation-node.candidate .node-body{fill:#a77b50}.relation-node.selected .node-halo{stroke:var(--accent);stroke-width:5}.relation-node text{fill:#fff;font-size:10px;font-weight:700;pointer-events:none}.relation-node .node-label{fill:var(--ink-soft);font-size:8px;font-weight:650;paint-order:stroke;stroke:var(--surface-muted);stroke-width:4px}.focus-chip{position:absolute;z-index:2;top:10px;left:10px;display:flex;align-items:center;gap:6px;padding:6px 7px;border:1px solid var(--line);border-radius:6px;background:color-mix(in srgb,var(--surface) 94%,transparent);font-size:8px}.focus-chip svg,.focus-chip b{color:var(--accent)}.focus-chip button{display:grid;place-items:center;padding:0;border:0;background:transparent;color:var(--muted);cursor:pointer}.graph-legend{position:sticky;z-index:2;left:10px;bottom:10px;width:max-content;max-width:calc(100% - 20px);display:flex;flex-wrap:wrap;gap:8px;margin:-42px 0 10px 10px;padding:6px 8px;border:1px solid var(--line);border-radius:6px;background:color-mix(in srgb,var(--surface) 94%,transparent)}.graph-legend span{display:flex;align-items:center;gap:4px;color:var(--muted);font-size:7px}.graph-legend i{width:8px;height:8px;border-radius:50%;background:#78848f}.graph-legend i.self{background:#4f8bc9}.graph-legend i.target{background:var(--accent)}.graph-legend i.mutual{background:#5f8b72}.graph-legend i.group{background:#8569a9}.graph-legend i.candidate{background:#a77b50}.hidden-note{position:sticky;left:100%;bottom:10px;width:max-content;margin:-30px 10px 10px auto;color:var(--muted);font-size:7px}.node-inspector{padding:14px;border-left:1px solid var(--line);background:var(--surface